@@ -6682,17 +6680,13 @@ void PackLinuxElf32::un_shlib_1(
     struct {
         struct l_info l;
         struct p_info p;
-        struct b_info b;
     } hdr;
     fi->readx(&hdr, sizeof(hdr));
